-- MT2009_PLUS_YOHARA_MELEY_V1: the element of Schronienie Meley - the pl-wiki's "Element Ognia" of every monster, Idall and Meley
-- (setRaceFlag bit 4096); the statues and the eggs none. GENERATED by tools/yohara_meley/gen_ymeley.py. apply.sh runs
-- it AFTER zywioly_moby.sql, which clears bits 11-16 of every mob it does not list: idempotent.
SET NAMES utf8mb4;
-- ogien: 6110,6111,6112,6113,6114,6115,6116,6117,6193
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 4096 WHERE vnum IN (6110,6111,6112,6113,6114,6115,6116,6117,6193);
-- no element (the statues, the eggs): 6118,20422
UPDATE world.mob_proto SET setRaceFlag = (setRaceFlag + 0) & ~129024 WHERE vnum IN (6118,20422) AND (setRaceFlag + 0) & 129024 <> 0;
